  // cool electric ramp root->tips, frontier whitened by glow
  let hue = 0.55 + 0.30 * in.colorT;
  var col = hsv2rgb(hue, 0.7, 1.0);
  col = mix(col, vec3f(1.0), clamp(in.glow - 1.0, 0.0, 1.0) * 0.7);
