  let p = mix(psi[ix], psi[ix + 1], fx);
  let rho = p.x * p.x + p.y * p.y;
  let h = sqrt(max(rho, 0.0)) * hScale;
  let xw = in.uv.x * L;

  var col = vec3f(0.02, 0.02, 0.04);
