  if (abs(xw - xb) < hw && in.uv.y < V0n) { col = vec3f(0.22, 0.04, 0.05); }
  // energy line
  if (abs(in.uv.y - E0n) < 0.004) { col = mix(col, vec3f(1.0, 0.9, 0.35), 0.85); }
  // |psi|^2 fill
  if (in.uv.y < h) {
    var pc = vec3f(0.25, 0.7, 0.95);                 // incident / reflected
    if (xw > xb + hw) { pc = vec3f(0.3, 1.0, 0.45); } // transmitted
    else if (xw > xb - hw) { pc = vec3f(0.9, 0.9, 1.0); }   // inside barrier (tail)
    let edge = smoothstep(h, h - 0.02, in.uv.y);
    col = col * (1.0 - 0.85 * edge) + pc * (0.6 * edge + 0.25);
  }
