  basisR: vec4f,   // right.xyz, w = aspect
  basisU: vec4f,   // up.xyz,    w = tanHalfFov
  basisF: vec4f,   // forward.xyz, w = time
  motion: vec4f,   // motionDir.xyz, w = beta
