  // Sharper normal encoding: higher strength gives the bumps more
  // perceived depth in the lit shading.
  let strength = 3.5;
  let nx = clamp(-gx * strength * 0.5 + 0.5, 0.0, 1.0);
  let ny = clamp(-gy * strength * 0.5 + 0.5, 0.0, 1.0);
